# @@ recursive
def factorial(n) {
    if n <= 1 {
        return 1
    }
    return n * factorial(n - 1)
}

# @@ with a loop
def factorial_loop(n) {
    p = 1
    for k from 2 to n + 1 {
        p *= k
    }
    return p
}

