# @@ move n disks from one peg to another
def hanoi(n, source, target, spare) {
    if n == 0 {
        return []
    }
    moves = hanoi(n - 1, source, spare, target)
    moves = append(moves, f"disk {n:d}: {source} -> {target}")
    return moves + hanoi(n - 1, spare, target, source)
}

