# @@ merge two sorted lists
def merge(a, b) {
    out = []
    i = 0
    j = 0
    while i < len(a) and j < len(b) {
        if a[i] <= b[j] {
            out = append(out, a[i])
            i += 1
        }
        else {
            out = append(out, b[j])
            j += 1
        }
    }
    out = extend(out, a[i:])
    out = extend(out, b[j:])
    return out
}

# @@ split, sort each half, merge
def merge_sort(xs) {
    if len(xs) <= 1 {
        return xs
    }
    mid = len(xs) // 2
    return merge(merge_sort(xs[:mid]), merge_sort(xs[mid:]))
}

