# @@ partition around the last element
def partition(a, lo, hi) {
    pivot = a[hi]
    i = lo
    for j from lo to hi {
        if a[j] < pivot {
            a[i], a[j] = a[j], a[i]
            i += 1
        }
    }
    a[i], a[hi] = a[hi], a[i]
    return i
}

# @@ sort the two sides
def quicksort(a, lo, hi) {
    if lo < hi {
        p = partition(a, lo, hi)
        quicksort(a, lo, p - 1)
        quicksort(a, p + 1, hi)
    }
}

