def median(xs) {
    s = copy(xs)
    sort(s)
    n = len(s)
    mid = n // 2
    if n % 2 == 1 {
        return s[mid]
    }
    return 0.5 * (s[mid - 1] + s[mid])
}

def normalize(xs) {
    return xs / sum(xs)
}

